import java.util.*;

/**
 * Created by naveen on 19-Dec-15.
 */
public class test {

    public static void main(String[] args) {

        Scanner scn = new Scanner(System.in);

        int totalLength = Integer.parseInt(scn.nextLine());
        String lineInput = scn.nextLine();

        int braceWords = 0;
        int longestWord = 0;

        boolean insideParentheses = false;

        StringBuilder currentWord = new StringBuilder();

        for (int i = 0; i < totalLength; i++) {
            char c = lineInput.charAt(i);

            if (c == '_') {
                processWord(currentWord, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWords++;
                        } else {
                            longestWord = Math.max(longestWord, len);
                        }
                    }
                });
                currentWord = new StringBuilder();
            } else if (c == '(') {
                processWord(currentWord, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWords++;
                        } else {
                            longestWord = Math.max(longestWord, len);
                        }
                    }
                });
                currentWord = new StringBuilder();
                insideParentheses = true;
            } else if (c == ')') {
                processWord(currentWord, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWords++;
                        } else {
                            longestWord = Math.max(longestWord, len);
                        }
                    }
                });
                currentWord = new StringBuilder();
                insideParentheses = false;
            } else if (Character.isLetter(c)) {
                currentWord.append(c);
            }
        }

        processWord(currentWord, insideParentheses, (len) -> {
            if (len > 0) {
                if (insideParentheses) {
                    braceWords++;
                } else {
                    longestWord = Math.max(longestWord, len);
                }
            }
        });

        System.out.println(longestWord + " " + braceWords);
    }

    private static void processWord(StringBuilder word, boolean inBraces, java.util.function.IntConsumer consumer) {
        int length = word.length();
        if (length > 0) {
            consumer.accept(length);
        }
    }
}
